 item={'code':code,'url':urls[key].removesuffix('.js'),'set_price':price,'currency':currency,'set_contents':{'batteries':2,'dual_chargers':1},'available_boolean':d['available'],'numeric_stock':None,'scope':'Availability flag is not numeric stock/leadtime. No volume price breaks. Retail extensions exclude unknown freight/tax.','batch_scenarios':[]}
